const $=s=>document.querySelector(s),dialog=$('#onboarding');
let step=0,gooseMoved=false,jumps=0,stopped=false;
const icon=(type)=>`<span class="mini-piece ${type}" aria-hidden="true"></span>`;
function showStep(){
 $('#lesson-count').textContent=`0${step+1} / 03`;
 [...document.querySelectorAll('.lesson-progress i')].forEach((el,i)=>el.classList.toggle('done',i<=step));
 $('#lesson-back').hidden=step===0;$('#lesson-next').textContent=['Meet the geese','Meet the fox','Let’s play'][step];
 if(step===0){$('#lesson-content').innerHTML=`<h2 id="lesson-title" tabindex="-1">One board.<br>Two very different plans.</h2><p class="lesson-intro">You and your opponent take turns. The geese go first. Each turn, move one piece along the engraved lines.</p><div class="lesson-sides"><div>${icon('goose')}<h3>Thirteen geese</h3><p>Work together to <strong>trap the fox</strong>. You win when it has no legal step or jump at the start of its turn.</p></div><div>${icon('fox')}<h3>One fox</h3><p>Jump over geese to capture them. <strong>Capture eight</strong> and win immediately when only five remain.</p></div></div><p class="lesson-tip">Choose either side at the table, or select Two players to take turns on the same device.</p>`;}
 if(step===1){gooseMoved=false;$('#lesson-content').innerHTML=`<h2 id="lesson-title" tabindex="-1">Build a wall.</h2><p class="lesson-intro">A goose moves <strong>one point forward or sideways</strong> into an empty spot. Forward means toward the top—including diagonals where a line is drawn.</p><div class="practice-label">TRY IT · CHOOSE A GLOWING POINT</div><div class="goose-demo" role="group" aria-label="Practice moving a goose"><span class="forward-label">FORWARD · TOWARD THE TOP</span><svg viewBox="0 0 300 240" aria-hidden="true"><path d="M55 45H150H245M55 120H150H245M55 195H150H245M55 45V120V195M150 45V120V195M245 45V120V195M55 45 150 120 245 195M245 45 150 120 55 195"/></svg><div id="demo-goose" class="demo-token goose" style="left:50%;top:50%">${icon('goose')}</div>${[[55,45],[150,45],[245,45],[55,120],[245,120]].map(([x,y],i)=>`<button class="demo-destination" style="left:${x/3}%;top:${y/2.4}%" data-x="${x}" data-y="${y}" aria-label="Move goose ${['diagonally forward left','forward','diagonally forward right','sideways left','sideways right'][i]}"></button>`).join('')}${[55,150,245].map(x=>`<span class="demo-point" style="left:${x/3}%;top:81.25%"></span>`).join('')}</div><p class="practice-feedback" id="practice-feedback" role="status">No backward moves. Geese never jump or capture.</p><p class="lesson-tip"><strong>A little strategy:</strong> keep your geese close. A goose with an empty space behind it can be jumped.</p>`;
 for(const b of document.querySelectorAll('.demo-destination'))b.onclick=()=>{if(gooseMoved)return;gooseMoved=true;Object.assign($('#demo-goose').style,{left:`${Number(b.dataset.x)/3}%`,top:`${Number(b.dataset.y)/2.4}%`});for(const el of document.querySelectorAll('.demo-destination'))el.disabled=true;$('#practice-feedback').textContent='Exactly. One goose, one connected step. Then it’s the fox’s turn.';};}
 if(step===2){jumps=0;stopped=false;$('#lesson-content').innerHTML=`<h2 id="lesson-title" tabindex="-1">Find the opening.</h2><p class="lesson-intro">The fox can step one point in <strong>any direction</strong>. Or jump over an adjacent goose to the empty point immediately beyond it, along a straight drawn line.</p><div class="practice-label">TRY IT · CHOOSE THE AMBER RING</div><div class="fox-demo" role="group" aria-label="Practice an optional capture chain"><svg viewBox="0 0 360 130" aria-hidden="true"><path d="M40 65H320"/></svg>${[40,110,180,250,320].map(x=>`<span class="demo-point" style="left:${x/3.6}%;top:50%"></span>`).join('')}<div class="demo-token" id="demo-fox" style="left:11.111%;top:50%">${icon('fox')}</div><div class="demo-token" id="capture-one" style="left:30.556%;top:50%">${icon('goose')}</div><div class="demo-token" id="capture-two" style="left:69.444%;top:50%">${icon('goose')}</div><button class="demo-destination amber" id="demo-jump" style="left:50%;top:50%" aria-label="Jump over the first goose"></button></div><div class="capture-choice"><p class="practice-feedback" id="practice-feedback" role="status">Jump to the empty ring. The goose you cross is captured.</p><button class="quiet" id="demo-stop" hidden>Stop here</button></div><p class="lesson-tip"><strong>You choose:</strong> capturing is never compulsory. After a jump, keep jumping if another capture is available—or use <strong>End capture turn</strong>. You cannot take a normal step after a jump.</p>`;
 $('#demo-jump').onclick=()=>{if(stopped||jumps>=2)return;jumps++;$('#demo-fox').style.left=jumps===1?'50%':'88.889%';$(jumps===1?'#capture-one':'#capture-two').classList.add('demo-captured');if(jumps===1){$('#demo-jump').style.left='88.889%';$('#demo-jump').ariaLabel='Jump over the second goose';$('#demo-stop').hidden=false;$('#practice-feedback').textContent='One captured. Jump again, or stop here and let the geese move.';}else{$('#demo-jump').hidden=true;$('#demo-stop').hidden=true;$('#practice-feedback').textContent='Two captures in one turn. No more jumps here—the geese move next.';}};
 $('#demo-stop').onclick=()=>{stopped=true;$('#demo-jump').hidden=true;$('#demo-stop').hidden=true;$('#practice-feedback').textContent='A perfectly legal choice. Keep your position and let the geese move.';};}
}
function remember(){try{localStorage.setItem('fox-geese-onboarding-v1','seen');}catch{}}
function openTour(){step=0;showStep();dialog.showModal();}
function closeTour(){remember();dialog.close();}
$('#rules-button').onclick=openTour;$('#replay-tour').onclick=()=>{$('#rules').close();openTour();};$('#skip-tour').onclick=closeTour;
$('#lesson-next').onclick=()=>{if(step===2){closeTour();return;}step++;showStep();$('#lesson-title').focus({preventScroll:true});dialog.scrollTop=0;};$('#lesson-back').onclick=()=>{step=Math.max(0,step-1);showStep();$('#lesson-title').focus({preventScroll:true});dialog.scrollTop=0;};
$('#all-rules').onclick=()=>{closeTour();$('#rules').showModal();};dialog.addEventListener('close',remember);
let seen=false;try{seen=localStorage.getItem('fox-geese-onboarding-v1')==='seen';}catch{}if(!seen)openTour();
